import{_ as e,o as t,c as n,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"1. Vad är en databas?","description":"","frontmatter":{},"headers":[],"relativePath":"sv/chapters/01-vad-ar-en-databas.md","filePath":"sv/chapters/01-vad-ar-en-databas.md"}'),s={name:"sv/chapters/01-vad-ar-en-databas.md"};function i(l,a,d,o,p,h){return t(),n("div",null,[...a[0]||(a[0]=[r(`<h1 id="_1-vad-ar-en-databas" tabindex="-1">1. Vad är en databas? <a class="header-anchor" href="#_1-vad-ar-en-databas" aria-label="Permalink to &quot;1. Vad är en databas?&quot;">​</a></h1><p>Vi människor har alltid behövt hålla reda på saker. Vilka varor finns i lager? Vem äger ett hus? Hur mycket pengar finns på ett konto? Vilka elever går i en viss klass?</p><p>Vi kan skriva ner informationen på papper, spara den i filer eller hålla den i minnet. Men när mängden information växer behöver vi kunna organisera den så att den blir enkel att hitta, använda och förändra.</p><p>Det är i grunden vad databaser handlar om.</p><h2 id="grund" tabindex="-1">Grund <a class="header-anchor" href="#grund" aria-label="Permalink to &quot;Grund&quot;">​</a></h2><h3 id="data-nycklar-och-varden" tabindex="-1">Data, nycklar och värden <a class="header-anchor" href="#data-nycklar-och-varden" aria-label="Permalink to &quot;Data, nycklar och värden&quot;">​</a></h3><p>Vi kan börja med något mycket enkelt:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Förnamn: Benjamin</span></span></code></pre></div><p>Här har vi en <strong>nyckel</strong> (<code>Förnamn</code>) och ett <strong>värde</strong> (<code>Benjamin</code>).</p><p>Nyckeln beskriver vad informationen handlar om och värdet innehåller själva uppgiften.</p><p>Om vi samlar flera sådana uppgifter kan vi beskriva exempelvis en kund i en bokhandel:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kund:</span></span>
<span class="line"><span>    Förnamn: Benjamin</span></span>
<span class="line"><span>    Efternamn: Berglund</span></span>
<span class="line"><span>    Telefon: 0123-456789</span></span>
<span class="line"><span>    Adress:</span></span>
<span class="line"><span>        Gata: Hemmagatan 1</span></span>
<span class="line"><span>        Postnummer: 124 56</span></span>
<span class="line"><span>        Ort: Hemmavan</span></span></code></pre></div><p>Nu har vi skapat en enkel datastruktur. Vi har också grupperat några av uppgifterna: gatan, postnumret och orten beskriver tillsammans en adress.</p><p>Samma information kan representeras på flera olika sätt.</p><p>I JavaScript kan vi exempelvis skriva:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> customer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    firstName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Benjamin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    lastName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Berglund&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    phone: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0123-456789&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    address: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        street: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hemmagatan 1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        postalCode: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;124 56&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        city: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hemmavan&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>Men vi skulle också kunna organisera informationen i en tabell.</p><h3 id="tabeller" tabindex="-1">Tabeller <a class="header-anchor" href="#tabeller" aria-label="Permalink to &quot;Tabeller&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Förnamn</th><th>Efternamn</th><th>Telefon</th><th>Ort</th></tr></thead><tbody><tr><td>Benjamin</td><td>Berglund</td><td>0123-456789</td><td>Hemmavan</td></tr><tr><td>Olof</td><td>Olofsson</td><td>0231-564789</td><td>Storfors</td></tr><tr><td>Anaïs</td><td>Martin</td><td>+43 21-976 542</td><td>Loire</td></tr></tbody></table><p>Här beskriver varje <strong>rad</strong> en kund, och varje <strong>kolumn</strong> en viss typ av uppgift om kunden.</p><p>Vi kan förstå tabellen genom tre enkla begrepp:</p><ul><li><strong>Tabell:</strong> En samling uppgifter som hör ihop.</li><li><strong>Rad:</strong> En enskild post, exempelvis en kund.</li><li><strong>Kolumn:</strong> En viss egenskap hos posterna, exempelvis förnamn.</li></ul><p>I en relationell databas bygger vi upp vår information med sådana tabeller.</p><h3 id="vad-gor-detta-till-en-databas" tabindex="-1">Vad gör detta till en databas? <a class="header-anchor" href="#vad-gor-detta-till-en-databas" aria-label="Permalink to &quot;Vad gör detta till en databas?&quot;">​</a></h3><p>En tabell i ett dokument eller kalkylblad är inte automatiskt en databas.</p><p>En <strong>databas</strong> är en organiserad samling data som kan lagras, hanteras och användas. För att arbeta med den använder vi vanligtvis ett <strong>databashanteringssystem</strong> (DBMS, Database Management System).</p><p>I relationella databaser använder vi frågespråket <strong>SQL (Structured Query Language)</strong> för att läsa, lägga till, förändra och ta bort information. SQL är utformat för att likna vanlig engelska, samtidigt som språket har en tydlig struktur som datorer kan tolka.</p><p>Exempel på databashanteringssystem som använder SQL är MySQL, PostgreSQL, SQLite och Microsoft SQL Server.</p><p>Databashanteraren hjälper oss bland annat att:</p><ul><li>Lagra och hämta information.</li><li>Lägga till, ändra och ta bort uppgifter.</li><li>Söka efter information som uppfyller vissa villkor.</li><li>Kontrollera att informationen följer bestämda regler.</li><li>Hantera att flera användare arbetar med samma information.</li></ul><p>Skillnaden mellan databasen och databashanteraren kan jämföras med skillnaden mellan ett dokument och programmet som hanterar dokumentet.</p><h3 id="att-stalla-fragor-till-informationen" tabindex="-1">Att ställa frågor till informationen <a class="header-anchor" href="#att-stalla-fragor-till-informationen" aria-label="Permalink to &quot;Att ställa frågor till informationen&quot;">​</a></h3><p>Anta att bokhandeln har en databas med tusentals kunder.</p><p>Vi kanske vill veta vilka kunder som bor i Hemmavan, eller vilka som har ett efternamn som börjar med B.</p><p>Vi skulle kunna läsa igenom alla poster manuellt, men det vore knappast praktiskt.</p><p>I stället kan vi ställa en fråga till databasen.</p><p>Med SQL kan en sådan fråga se ut så här:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> customers</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> city </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Hemmavan&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Vi behöver inte förstå syntaxen än. Det viktiga är att vi beskriver <strong>vilken information vi vill ha</strong>, snarare än hur databashanteraren ska leta efter den.</p><p>Detta är en grundläggande idé bakom SQL.</p><h3 id="relationer-mellan-data" tabindex="-1">Relationer mellan data <a class="header-anchor" href="#relationer-mellan-data" aria-label="Permalink to &quot;Relationer mellan data&quot;">​</a></h3><p>Låt oss anta att bokhandeln också behöver hålla reda på kundernas adresser.</p><p>Vi skulle kunna lagra gatuadress, postnummer och ort tillsammans med varje kund. Men vad händer när en kund vill ha en separat leveransadress? Eller när adressuppgifter behöver förändras?</p><p>Ett annat sätt är att lagra kunder och adresser i separata tabeller och beskriva hur de hör ihop.</p><p><strong>Kunder (customers)</strong></p><table tabindex="0"><thead><tr><th>id</th><th>name</th></tr></thead><tbody><tr><td>1</td><td>Benjamin</td></tr><tr><td>2</td><td>Olof</td></tr></tbody></table><p><strong>Adresser (addresses)</strong></p><table tabindex="0"><thead><tr><th>id</th><th>customer_id</th><th>street</th><th>city</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>Hemmagatan 1</td><td>Hemmavan</td></tr><tr><td>2</td><td>1</td><td>Storgatan 4</td><td>Storfors</td></tr><tr><td>3</td><td>2</td><td>Parkvägen 2</td><td>Storfors</td></tr></tbody></table><p>Kolumnen <code>customer_id</code> innehåller kundens id och visar vilken kund varje adress hör till.</p><p>Nu kan en kund ha flera adresser, utan att vi behöver skapa fler adresskolumner i kundtabellen.</p><p>Detta är en av de viktigaste principerna bakom relationella databaser: vi kan organisera uppgifter om olika saker var för sig, samtidigt som vi bevarar sambanden mellan dem.</p><p>Vi kommer att återkomma till hur relationer fungerar i senare kapitel.</p><h2 id="avancerat" tabindex="-1">Avancerat <a class="header-anchor" href="#avancerat" aria-label="Permalink to &quot;Avancerat&quot;">​</a></h2><h3 id="en-databas-ar-en-modell-av-verkligheten" tabindex="-1">En databas är en modell av verkligheten <a class="header-anchor" href="#en-databas-ar-en-modell-av-verkligheten" aria-label="Permalink to &quot;En databas är en modell av verkligheten&quot;">​</a></h3><p>När vi lagrar information beskriver vi inte hela verkligheten. Vi väljer ut de egenskaper och samband som är relevanta för vårt syfte.</p><p>En kund har betydligt fler egenskaper än namn och adress. Men om vi bygger ett kundregister kanske det är allt vi behöver veta.</p><p>När bokhandeln senare ska hantera beställningar, produkter och betalningar behöver vi andra uppgifter och andra samband.</p><p>Det innebär att en databas inte bara är ett sätt att lagra information. <strong>Den är också en modell av den del av verkligheten vi vill beskriva.</strong></p><p>Modellen påverkar vad vi senare kan fråga efter, beräkna och dra slutsatser om.</p><h3 id="ar-alla-databaser-relationella" tabindex="-1">Är alla databaser relationella? <a class="header-anchor" href="#ar-alla-databaser-relationella" aria-label="Permalink to &quot;Är alla databaser relationella?&quot;">​</a></h3><p>Nej.</p><p>Information kan organiseras på olika sätt, och olika databastyper är lämpliga för olika problem.</p><p>Exempelvis:</p><table tabindex="0"><thead><tr><th>Databastyp</th><th>Grundläggande idé</th></tr></thead><tbody><tr><td>Relationell</td><td>Information organiseras i tabeller med definierade samband.</td></tr><tr><td>Dokumentorienterad</td><td>Information organiseras som dokument, exempelvis JSON.</td></tr><tr><td>Nyckel-värde</td><td>Information hämtas och lagras med hjälp av identifierande nycklar.</td></tr><tr><td>Grafdatabas</td><td>Information representeras som noder och relationer mellan dessa.</td></tr></tbody></table><p>Det finns många fler varianter och kombinationer.</p><p>Den här boken handlar framför allt om <strong>relationella databaser och SQL</strong>, men många av resonemangen kring hur vi representerar och organiserar information är relevanta även för andra databastyper.</p><h3 id="data-och-datatyper" tabindex="-1">Data och datatyper <a class="header-anchor" href="#data-och-datatyper" aria-label="Permalink to &quot;Data och datatyper&quot;">​</a></h3><p>Hittills har vi beskrivit information med text och tabeller. Men alla värden är inte av samma slag.</p><p>Exempelvis:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Namn: Anna</span></span>
<span class="line"><span>Ålder: 27</span></span>
<span class="line"><span>Pris: 149.50</span></span>
<span class="line"><span>Registrerad: 2026-01-15</span></span>
<span class="line"><span>Aktiv: Ja</span></span></code></pre></div><p>Vi vill kunna göra olika saker med dessa värden.</p><p>Ett namn kan vi jämföra eller söka efter. En ålder kan vi räkna med. Ett datum kan vi jämföra med andra datum.</p><p>Databaser använder därför <strong>datatyper</strong> för att beskriva vilken sorts värden som kan lagras i en kolumn.</p><p>Det hjälper databashanteraren att tolka och bearbeta informationen på ett förutsägbart sätt.</p><p>Vi kommer att gå närmare in på datatyper när vi börjar skapa egna tabeller.</p><h3 id="databasens-ansvar" tabindex="-1">Databasens ansvar <a class="header-anchor" href="#databasens-ansvar" aria-label="Permalink to &quot;Databasens ansvar&quot;">​</a></h3><p>Vi har redan sett att en databas kan lagra information och besvara frågor.</p><p>Men vad händer om två användare försöker förändra samma uppgift samtidigt? Eller om en ändring avbryts innan den är färdig?</p><p>En databashanterare behöver kunna hantera sådana situationer utan att informationen blir motsägelsefull eller går förlorad.</p><p>Det är bland annat därför vi använder databashanterare i stället för att bara skriva och läsa vanliga textfiler.</p><p>Senare i boken kommer vi att undersöka hur databaser upprätthåller dataintegritet, hanterar transaktioner och gör information tillgänglig för flera användare.</p><h2 id="reflektion" tabindex="-1">Reflektion <a class="header-anchor" href="#reflektion" aria-label="Permalink to &quot;Reflektion&quot;">​</a></h2><ol><li>Vad är egentligen skillnaden mellan att lagra information och att organisera information?</li><li>Hur påverkas en datamodell av vad vi vill använda informationen till?</li><li>Finns det situationer där en vanlig fil är en bättre lösning än en databas?</li></ol>`,83)])])}const g=e(s,[["render",i]]);export{m as __pageData,g as default};
